CREATE TABLE hive_scans (id TEXT PRIMARY KEY, public_id TEXT NOT NULL UNIQUE, producer_id TEXT NOT NULL REFERENCES producers(id), apiary_id TEXT NOT NULL REFERENCES apiaries(id), hive_id TEXT REFERENCES hives(id), mode TEXT NOT NULL CHECK(mode IN ('HONEY_QUALITY','ENVIRONMENT','DISEASE','DIGITAL_TWIN')), source TEXT NOT NULL CHECK(source IN ('camera','upload')), capture_digest TEXT NOT NULL, duration_seconds REAL NOT NULL, frame_count INTEGER NOT NULL, frame_keys TEXT NOT NULL DEFAULT '[]', score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 100), classification TEXT NOT NULL CHECK(classification IN ('LOW','MEDIUM','HIGH')), report_json TEXT NOT NULL, engine_version TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE INDEX scans_producer ON hive_scans(producer_id,created_at DESC);
CREATE INDEX scans_hive ON hive_scans(hive_id,created_at DESC);
CREATE TABLE consumer_reviews (id TEXT PRIMARY KEY, producer_id TEXT NOT NULL REFERENCES producers(id), batch_id TEXT REFERENCES batches(id), reviewer TEXT NOT NULL, channel TEXT NOT NULL, rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), title TEXT NOT NULL, body TEXT NOT NULL, sentiment TEXT NOT NULL CHECK(sentiment IN ('positive','neutral','negative')), tags TEXT NOT NULL DEFAULT '[]', verified_scan INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE INDEX reviews_producer ON consumer_reviews(producer_id,created_at DESC);
